#pragma GCC optimize("Ofast,unroll-loops")
#pragma GCC target("avx2")

static const int MAXN = 4005;
static const int MAXK = 805;
static const long long INF = (long long)4e18;

int n, k;
int a[MAXN][MAXN];
int pref[MAXN][MAXN];
int C[MAXN][MAXN];
long long dp0[MAXN], dp1[MAXN];
long long *dp_prev = dp0, *dp_cur = dp1;

static const int BUFSZ = 1<<20;
static char buf[BUFSZ];
static int buf_pos = 0, buf_len = 0;
inline int readChar() {
    if (buf_pos == buf_len) {
        buf_pos = 0;
        buf_len = fread(buf,1,BUFSZ,stdin);
        if (!buf_len) return EOF;
    }
    return buf[buf_pos++];
}
inline int readInt() {
    int c = readChar(), x = 0;
    while (c <= ' ') c = readChar();
    for (; c >= '0' && c <= '9'; c = readChar())
        x = x*10 + (c & 15);
    return x;
}

void build() {
    for(int i = 1; i <= n; ++i) {
        int row_acc = 0;
        for(int j = 1; j <= n; ++j) {
            row_acc += a[i][j];
            pref[i][j] = pref[i-1][j] + row_acc;
        }
    }
}

void build1() {
    for(int l = 1; l <= n; ++l) {
        for(int r = l; r <= n; ++r) {
            int total = pref[r][r]
                      - pref[l-1][r]
                      - pref[r][l-1]
                      + pref[l-1][l-1];
            C[l][r] = total >> 1;  
        }
    }
}

void build2(int d) {
    struct Frame { int L,R,optL,optR; };
    static Frame st[64];
    int sp = 0;
    st[sp++] = {d, n, d, n};

    while(sp) {
        auto f = st[--sp];
        int L = f.L, R = f.R, optL = f.optL, optR = f.optR;
        if (L > R) continue;
        int mid = (L + R) >> 1;

        long long best = INF;
        int bestk = optL;
        int hi = mid < optR ? mid : optR;
        for(int j = optL; j <= hi; ++j) {
            long long cand = dp_prev[j-1] + C[j][mid];
            if (cand < best) {
                best = cand;
                bestk = j;
            }
        }
        dp_cur[mid] = best;

        st[sp++] = {mid+1, R,   bestk, optR};
        st[sp++] = {L,     mid-1, optL, bestk};
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    n = readInt();
    k = readInt();
    for(int i = 1; i <= n; ++i)
        for(int j = 1; j <= n; ++j)
            a[i][j] = readInt();

    build();
    build1();

    for(int i = 0; i <= n; ++i) dp_prev[i] = INF;
    dp_prev[0] = 0;

    for(int d = 1; d <= k; ++d) {

        for(int i = 0; i <= n; ++i) dp_cur[i] = INF;

        build2(d);

        swap(dp_prev, dp_cur);
    }

    printf("%lld\n", dp_prev[n]);
}